#!/usr/bin/env node
// embed-icon.mjs — writes the KATAK icon (design/icon/katak-icon.svg, the owner's choice, generated by design/icon/build-icons.mjs)
// INTO kalculator/index.html between the ICON-BEGIN / ICON-END markers, as an inline <svg class="logo">. The page is
// self-contained: it loads no file outside itself (owner 2026-11-16 16:50 «HTML наш самодостаточен»; HOUSE_RULES.md R7).
// The tab icon is built by the page from the same inline copy, so one copy serves both.
//
//   node tools/embed-icon.mjs            # rewrite the copy in the page
//   node tools/embed-icon.mjs --check    # exit 1 when the copy in the page differs from the icon file (the truth↔mirror pair)
//
// Pair: truth design/icon/katak-icon.svg → mirror kalculator/index.html (ICON-BEGIN…ICON-END). [NOT-TESTED]
import { readFileSync, writeFileSync } from 'node:fs';

const ICON = 'design/icon/katak-icon.svg', PAGE = 'kalculator/index.html';
const BEGIN = '<!-- ICON-BEGIN', END = '<!-- ICON-END -->';

const svg = readFileSync(ICON, 'utf8')
  .replace(/<\?xml[^>]*\?>/g, '')
  .replace(/<!--[\s\S]*?-->/g, '')                  // the generator's comment stays in the file, not in the page
  .replace(/\n\s*\n/g, '\n')
  .trim()
  .replace('<svg ', '<svg class="logo" aria-hidden="true" focusable="false" ');

const html = readFileSync(PAGE, 'utf8');
const b = html.indexOf(BEGIN), bEnd = html.indexOf('-->', b) + 3, e = html.indexOf(END);
if (b < 0 || e < 0 || bEnd < 3 || e < bEnd) { console.error(`embed-icon: markers ${BEGIN} … ${END} not found in ${PAGE}`); process.exit(2); }
const eol = html.includes('\r\n') ? '\r\n' : '\n';
const next = html.slice(0, bEnd) + eol + '    ' + svg.split(/\r?\n/).join(eol) + eol + '    ' + html.slice(e);

if (process.argv.includes('--check')) {
  const same = next === html;
  console.log(same ? `embed-icon --check: OK — the page carries the current ${ICON}` : `embed-icon --check: DRIFT — the copy in ${PAGE} differs from ${ICON}; run node tools/embed-icon.mjs`);
  process.exit(same ? 0 : 1);
}
writeFileSync(PAGE, next);
console.log(`embed-icon: ${ICON} (${svg.length} chars) → ${PAGE}`);
